//! L2 Step 1b item (A) — the trading-session parity oracle.
//!
//! `checkTradingSession` was the one gate the entry point could not port blind: outside trading hours
//! the web refuses with MARKET_CLOSED and the engine would fill. This asserts
//! `order_management::session` against `docs/contracts/trading-session-vectors.json`, generated by
//! `scripts/contracts/gen-trading-session-vectors.ts` from the web's own function.
//!
//! Four rules compose into that gate, and all four are in the matrix:
//!   1. CRYPTO is always open
//!   2. the weekly close, Friday 17:00 -> Sunday 17:00 New York (both seasons, and both changeovers)
//!   3. the daily settlement break: METALS and SpotCrude 1 h, SpotBrent 3 h, Sunday..Thursday
//!   4. admin-configured TradingSession rows, which win over all of the above
//!
//! No database: both sides are pure.

use order_management::session::{self, SessionWindow};

fn vectors() -> serde_json::Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/contracts/trading-session-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("trading-session-vectors.json")).unwrap()
}

fn at(v: &serde_json::Value) -> chrono::DateTime<chrono::Utc> {
    v.as_str().expect("a UTC timestamp").parse().expect("parseable")
}

#[test]
fn the_engines_session_gate_matches_the_web_on_every_case() {
    let v = vectors();
    let cases = v["cases"].as_array().expect("cases");
    assert!(cases.len() >= 200, "the matrix shrank: {} cases", cases.len());

    let mut mismatches: Vec<String> = Vec::new();
    for c in cases {
        let now = at(&c["utc"]);
        let category = c["category"].as_str().unwrap();
        let symbol = c["symbol"].as_str();
        let sessions: Vec<SessionWindow> = c["sessions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| SessionWindow {
                day_of_week: s["dayOfWeek"].as_i64().unwrap() as i32,
                open_time: s["openTime"].as_str().unwrap().to_string(),
                close_time: s["closeTime"].as_str().unwrap().to_string(),
            })
            .collect();
        let expected = c["closed"].as_bool().unwrap();
        let got = session::is_market_closed(&sessions, now, category, symbol);
        if got != expected {
            mismatches.push(format!(
                "{} {category} {:?} sessions={} -> web closed={expected}, engine closed={got}   [{}]",
                c["utc"].as_str().unwrap(),
                symbol,
                sessions.len(),
                c["why"].as_str().unwrap_or("")
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} session cases disagree:\n{}",
        mismatches.len(),
        cases.len(),
        mismatches.join("\n")
    );
}

/// The helpers piece by piece, so a failure says WHICH rule drifted rather than only that the
/// composition did.
#[test]
fn every_session_helper_matches_the_web() {
    let v = vectors();
    let h = &v["helpers"];

    for c in h["usEasternIsDst"].as_array().unwrap() {
        assert_eq!(session::us_eastern_is_dst(at(&c["utc"])), c["value"].as_bool().unwrap(), "usEasternIsDst {}", c["utc"]);
    }
    for c in h["nyCloseHourUtc"].as_array().unwrap() {
        assert_eq!(session::ny_close_hour_utc(at(&c["utc"])) as i64, c["value"].as_i64().unwrap(), "nyCloseHourUtc {}", c["utc"]);
    }
    for c in h["dailyBreakHours"].as_array().unwrap() {
        let (category, symbol) = (c["category"].as_str().unwrap(), c["symbol"].as_str());
        assert_eq!(
            session::daily_break_hours(category, symbol) as i64,
            c["hours"].as_i64().unwrap(),
            "dailyBreakHours({category}, {symbol:?})"
        );
        assert_eq!(
            session::has_daily_break(category, symbol),
            c["hasBreak"].as_bool().unwrap(),
            "hasDailyBreak({category}, {symbol:?})"
        );
    }
    for c in h["isInDailyBreak"].as_array().unwrap() {
        assert_eq!(
            session::is_in_daily_break(at(&c["utc"]), c["category"].as_str().unwrap(), c["symbol"].as_str()),
            c["inBreak"].as_bool().unwrap(),
            "isInDailyBreak {} {}",
            c["utc"],
            c["category"]
        );
    }
    for c in h["isDefaultFxSessionClosed"].as_array().unwrap() {
        assert_eq!(
            session::is_default_fx_session_closed(at(&c["utc"])),
            c["closed"].as_bool().unwrap(),
            "isDefaultFxSessionClosed {}",
            c["utc"]
        );
    }
}
